import{_ as n,C as l,o as e,c as h,j as i,E as t,a as s,a2 as o}from"./chunks/framework.C21TwvGF.js";const N=JSON.parse(`{"title":"12-dars (Mentor). O'yin uchun ikonka va spraytlar yaratish (2-qism): Personaj va obyektlar uchun spraytlar chizish","description":"","frontmatter":{"title":"12-dars (Mentor). O'yin uchun ikonka va spraytlar yaratish (2-qism): Personaj va obyektlar uchun spraytlar chizish","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"week":{"n":4,"link":"/mentor/9-sinf-game/hafta-04/"},"g":12,"title":"O'yin uchun ikonka va spraytlar yaratish (2-qism): Personaj va obyektlar uchun spraytlar chizish","lead":"Mario ham bir paytlar bir necha o'nlab pikseldan iborat edi! Bugun 32×32 piksel ichida o'z qahramoningizni yaratasiz, unga tanga va zelye chizasiz va uni «nafas oldirasiz».","slide":"/slaydlar/9-sinf-game/hafta-04/dars-3.html","test":"/slaydlar/9-sinf-game/hafta-04/dars-3-test.html","student_link":"/9-sinf-game/hafta-04/dars-3","tabs":[{"g":10,"link":"/mentor/9-sinf-game/hafta-04/dars-1","current":false},{"g":11,"link":"/mentor/9-sinf-game/hafta-04/dars-2","current":false},{"g":12,"link":"/mentor/9-sinf-game/hafta-04/dars-3","current":true}],"prev":{"g":11,"title":"O'yin uchun ikonka va spraytlar yaratish (1-qism): Sprayt va ikonka tushunchasi, formatlar (PNG, SVG)","link":"/mentor/9-sinf-game/hafta-04/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-04/dars-3.md","filePath":"mentor/9-sinf-game/hafta-04/dars-3.md"}`),d={name:"mentor/9-sinf-game/hafta-04/dars-3.md"},g={class:"blk"},p={id:"dars-rejasi",tabindex:"-1"},y={class:"blk"},u={id:"mentor-konspekti",tabindex:"-1"},k={class:"blk"},m={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},q={class:"blk"},c={id:"tezkor-nazorat-savollari",tabindex:"-1"},b={class:"blk"},v={id:"keng-tarqalgan-xatolar-va-ularning-oldini-olish",tabindex:"-1"};function f(_,a,x,z,P,T){const r=l("Icon");return e(),h("div",null,[i("div",g,[i("h2",p,[t(r,{name:"file-text"}),a[0]||(a[0]=s(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=o("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga spraytlarni yaratish bosqichlarini (uslub va o&#39;lchamni aniqlash, eskiz va siluyet, cheklangan palitra bilan asosiy ranglar, soya va yorug&#39;lik, kontur, eksport va test) Photoshop&#39;da piksel-art usulida amalda bajarishni o&#39;rgatish; personaj va obyekt spraytlarining xususiyatlari, piksel to&#39;r (grid) bilan ishlash, Pencil Tool, Nearest Neighbor interpolyatsiyasi va oddiy 2 kadrli animatsiya (idle) tushunchasini berish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar 32×32 px qahramon spraytini va 16×16 yoki 32×32 px obyekt spraytini (tanga, zelye, sandiq) 10-dars palitrasida chizadi; siluyet testi va kulrang testdan o&#39;tkazadi; spraytni sifat yo&#39;qotmasdan (Nearest Neighbor) kattalashtirib, shaffof PNG ga eksport qiladi; nafas olish (idle) animatsiyasining 2 ta kadrini tayyorlaydi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>O&#39;tgan mavzuni takrorlash (ikonka turlari, PNG/SVG): 10 daqiqa</li><li>Yangi mavzu: Sprayt yaratish bosqichlari, personaj va obyekt: 15 daqiqa</li><li>Photoshop&#39;ni piksel-art uchun sozlash: 10 daqiqa</li><li>Amaliyot: qahramon spraytini bosqichma-bosqich chizish: 25 daqiqa</li><li>Obyekt spraytlari va 2 kadrli idle animatsiya: 15 daqiqa</li><li>Xulosa: 5 daqiqa</li></ul></li></ul><blockquote><p>Manba: o&#39;quv dasturi — «O&#39;yin uchun ikonka va spraytlar yaratish» moduli: «Spraytlarni yaratish bosqichlari ... Personaj va obyektlar uchun spraytlar», «Photoshopda ikonkalar yasash (HP, coin va boshqalar)»; o&#39;quv qo&#39;llanma — 2.3-bo&#39;lim, «Spraytlarni yaratish bosqichlari» (uslub va o&#39;lcham — «retro o&#39;yin uchun 32x32 pikselli spraytlar mos keladi», eskiz — «qalam» vositasi, detallar va rang — «chegaralangan ranglar palitrasi», soya va yorug&#39;lik, animatsiya kadrlari, «PNG yoki GIF formatida eksport qiling va ... sinab ko&#39;ring»). Sprayt sheet (atlas) va optimallashtirish — 13-dars mavzusi.</p></blockquote><hr>",3))]),i("div",y,[i("h2",u,[t(r,{name:"file-text"}),a[3]||(a[3]=s(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=o(`<h3 id="_1-personaj-va-obyekt-spraytlari" tabindex="-1">1. Personaj va obyekt spraytlari <a class="header-anchor" href="#_1-personaj-va-obyekt-spraytlari" aria-label="Permalink to &quot;1. Personaj va obyekt spraytlari&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Personaj spraytlari</th><th>Obyekt spraytlari</th></tr></thead><tbody><tr><td>Misollar</td><td>qahramon, dushman, NPC</td><td>tanga, zelye, sandiq, kalit, platforma</td></tr><tr><td>Asosiy talab</td><td>xarakter, tanilishi, harakat holatlari (idle, yurish, sakrash)</td><td>bir qarashda vazifasi tushunilishi</td></tr><tr><td>Animatsiya</td><td>deyarli doim</td><td>ko&#39;pincha oddiy (aylanish, yaltirash) yoki yo&#39;q</td></tr><tr><td>Rang</td><td>eng yuqori kontrast va to&#39;yinganlik</td><td>vazifaga ko&#39;ra rang kodlash (oltin — tanga, qizil — jon)</td></tr></tbody></table><h3 id="_2-sprayt-yaratishning-6-bosqichi-o-quv-qo-llanma-asosida" tabindex="-1">2. Sprayt yaratishning 6 bosqichi (o&#39;quv qo&#39;llanma asosida) <a class="header-anchor" href="#_2-sprayt-yaratishning-6-bosqichi-o-quv-qo-llanma-asosida" aria-label="Permalink to &quot;2. Sprayt yaratishning 6 bosqichi (o&#39;quv qo&#39;llanma asosida)&quot;">​</a></h3><ol><li><strong>Uslub va o&#39;lcham.</strong> Retro platformer uchun qahramon <strong>32×32 px</strong>, mayda obyektlar <strong>16×16 px</strong>. Barcha spraytlar bitta masshtabda bo&#39;lishi shart.</li><li><strong>Siluyet va eskiz.</strong> Avval bitta to&#39;q rang bilan <strong>siluyet</strong> (soyaning shakli): bosh, tana, qo&#39;l-oyoq, o&#39;ziga xos detal (shlyapa, qilich). Siluyet qora rangda ham tanilsa — dizayn yaxshi.</li><li><strong>Asosiy ranglar (flat).</strong> 10-darsdagi palitradan, har bir qism uchun bitta rang: teri, kiyim, soch, qurol. Qahramon uchun <strong>4–6 rang</strong> yetarli.</li><li><strong>Soya va yorug&#39;lik.</strong> Yorug&#39;lik manbai — <strong>yuqori chapda</strong> (barcha spraytlarda bir xil). Har rangga bitta soya (pastki o&#39;ng) va bitta yorug&#39;lik (yuqori chap) pog&#39;onasi — hue shifting bilan (10-dars).</li><li><strong>Kontur (outline).</strong> 1 px to&#39;q kontur — spraytni fondan ajratadi. Qora o&#39;rniga obyektning eng to&#39;q rangidan foydalanish yumshoqroq ko&#39;rinish beradi.</li><li><strong>Eksport va test.</strong> Shaffof PNG, o&#39;yin foniga qo&#39;yib tekshirish, kattalashtirib ko&#39;rish.</li></ol><h3 id="_3-photoshop-ni-piksel-art-uchun-sozlash" tabindex="-1">3. Photoshop&#39;ni piksel-art uchun sozlash <a class="header-anchor" href="#_3-photoshop-ni-piksel-art-uchun-sozlash" aria-label="Permalink to &quot;3. Photoshop&#39;ni piksel-art uchun sozlash&quot;">​</a></h3><ul><li><strong>Yangi hujjat:</strong> 32×32 px, 72 ppi, Background — <strong>Transparent</strong>. Ko&#39;rish uchun 800–1600% ga yaqinlashtiring (<code>Ctrl + +</code>).</li><li><strong>Piksel to&#39;ri:</strong> Edit → Preferences → <strong>Guides, Grid &amp; Slices</strong> → Gridline Every: <strong>1 pixel</strong>, Subdivisions: 1; so&#39;ng View → Show → <strong>Grid</strong> (<code>Ctrl + &#39;</code>).</li><li><strong>Pencil Tool</strong> (B guruhida, <code>Shift + B</code> bilan almashtiriladi) — <strong>Size 1 px</strong>, qattiq chet. Brush Tool emas: u chetlarni yumshatib, «xira» piksellar hosil qiladi.</li><li><strong>Eraser Tool</strong> (E) — Mode: <strong>Pencil</strong>, 1 px.</li><li><strong>Paint Bucket</strong> (G) — <strong>Anti-alias o&#39;chirilgan</strong>, Contiguous yoqilgan.</li><li><strong>Interpolyatsiya:</strong> Edit → Preferences → General → Image Interpolation: <strong>Nearest Neighbor (preserve hard edges)</strong>. Image Size bilan kattalashtirishda ham Resample: <strong>Nearest Neighbor</strong> tanlanadi — piksellar keskin qoladi.</li></ul><h3 id="_4-piksel-art-qoidalari" tabindex="-1">4. Piksel-art qoidalari <a class="header-anchor" href="#_4-piksel-art-qoidalari" aria-label="Permalink to &quot;4. Piksel-art qoidalari&quot;">​</a></h3><ul><li><strong>Bir piksel — bir qaror:</strong> har bir piksel ataylab qo&#39;yiladi.</li><li><strong>«Jaggies» dan qoching:</strong> chiziq bo&#39;laklari bir tekis o&#39;zgarsin (2-2-2 yoki 3-2-1), tartibsiz zinapoyalar emas.</li><li><strong>Orphan piksellar</strong> (yolg&#39;iz, hech narsaga ulanmagan piksel) — shovqin, o&#39;chiring.</li><li><strong>Doubles</strong> — kontur 2 px qalinlashib qolgan joylar; 1 px ga tushiring.</li><li><strong>Kam rang:</strong> qahramon uchun 4–6, butun sahna uchun 16–32 rang.</li></ul><h3 id="_5-qahramon-spraytini-chizish-namuna-32×32" tabindex="-1">5. Qahramon spraytini chizish: namuna (32×32) <a class="header-anchor" href="#_5-qahramon-spraytini-chizish-namuna-32×32" aria-label="Permalink to &quot;5. Qahramon spraytini chizish: namuna (32×32)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>Qatlamlar (pastdan yuqoriga):</span></span>
<span class="line"><span>  01_siluyet   - to&#39;q ko&#39;k-binafsha, keyin yashiriladi</span></span>
<span class="line"><span>  02_flat      - asosiy ranglar</span></span>
<span class="line"><span>  03_soya      - soyalar (Clipping Mask)</span></span>
<span class="line"><span>  04_yoruglik  - yorug&#39;lik dog&#39;lari (Clipping Mask)</span></span>
<span class="line"><span>  05_kontur    - 1 px kontur</span></span></code></pre></div><p>Nisbat (chibi/retro uslub): bosh ~ 12 px, tana ~ 10 px, oyoqlar ~ 8 px, tepada va pastda 1 px bo&#39;sh joy. Ko&#39;zlar — 1×2 px oq va to&#39;q piksellar.</p><h3 id="_6-obyekt-spraytlari" tabindex="-1">6. Obyekt spraytlari <a class="header-anchor" href="#_6-obyekt-spraytlari" aria-label="Permalink to &quot;6. Obyekt spraytlari&quot;">​</a></h3><ul><li><strong>Tanga (16×16):</strong> oltin doira, 1 px to&#39;q-jigarrang kontur, yuqori chapda 2–3 px oq yaltiroq, o&#39;rtada belgi.</li><li><strong>Zelye (16×16):</strong> shisha idish siluyeti, ichida rangli suyuqlik (qizil — jon, moviy — mana), oq aks.</li><li><strong>Sandiq (32×32):</strong> jigarrang yog&#39;och, oltin temir qoplamalar, qulf — o&#39;yinchiga «ochish mumkin» signalini beradi.</li></ul><p>Obyektlar personajdan <strong>oddiyroq</strong> va ko&#39;pincha <strong>kamroq to&#39;yingan</strong> bo&#39;ladi (bonuslardan tashqari).</p><h3 id="_7-oddiy-animatsiya-idle-nafas-olish-—-2-kadr" tabindex="-1">7. Oddiy animatsiya: idle (nafas olish) — 2 kadr <a class="header-anchor" href="#_7-oddiy-animatsiya-idle-nafas-olish-—-2-kadr" aria-label="Permalink to &quot;7. Oddiy animatsiya: idle (nafas olish) — 2 kadr&quot;">​</a></h3><ol><li>Tayyor qahramon qatlamlarini guruhlang → guruhni nusxalang (<code>Ctrl + J</code>).</li><li>2-kadrda tanani va boshni <strong>1 px pastga</strong> siljiting (Move Tool, <code>↓</code> strelka), oyoqlar joyida qoladi.</li><li><strong>Window → Timeline</strong> → <strong>Create Frame Animation</strong> → 1-kadrda 1-guruh ko&#39;rinadi, <strong>Duplicate frame</strong> → 2-kadrda 2-guruh.</li><li>Har kadr vaqti: <strong>0.5 sec</strong>, Looping: <strong>Forever</strong>. Play bilan tekshiring.</li><li>Eksport: kadrlarni alohida PNG (<code>sprayt_qahramon_idle_01.png</code>, <code>_02.png</code>) yoki <strong>File → Export → Save for Web (Legacy) → GIF</strong> — namoyish uchun.</li></ol><p>Kelgusi darsda (13-dars) kadrlar <strong>sprayt sheet (atlas)</strong> ga yig&#39;iladi.</p><h3 id="_8-eksport-va-test" tabindex="-1">8. Eksport va test <a class="header-anchor" href="#_8-eksport-va-test" aria-label="Permalink to &quot;8. Eksport va test&quot;">​</a></h3><ul><li><strong>Export As → PNG</strong>, Transparency ✓; masshtab 100% (o&#39;yin dvijoki o&#39;zi kattalashtiradi) va prezentatsiya uchun 800% (Nearest Neighbor bilan).</li><li><strong>Fon testi:</strong> spraytni 10-dars lokatsiya fonida tekshiring — kulrang testdan o&#39;tadimi?</li><li><strong>Masshtab testi:</strong> barcha spraytlar yonma-yon: tanga qahramondan kattami? Proporsiyalar to&#39;g&#39;rimi?</li></ul><hr>`,20))]),i("div",k,[i("h2",m,[t(r,{name:"file-text"}),a[6]||(a[6]=s(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=o('<h3 id="_1-topshiriq-siluyet-testi-oson" tabindex="-1">1-topshiriq. Siluyet testi (oson) <a class="header-anchor" href="#_1-topshiriq-siluyet-testi-oson" aria-label="Permalink to &quot;1-topshiriq. Siluyet testi (oson)&quot;">​</a></h3><p>Uch xil qahramon g&#39;oyasi uchun 32×32 px da faqat bitta to&#39;q rang bilan siluyet chizing (ritsar, sehrgar, robot). Sinfdoshingiz siluyetga qarab kimligini topa oladimi?</p><p><strong>Yechim:</strong> Ritsar — dubulg&#39;a pati va qalqon; sehrgar — uchli shlyapa va tayoq; robot — to&#39;rtburchak bosh va antenna. Har biriga bitta o&#39;ziga xos «chiqib turgan» detal kerak — u kichik o&#39;lchamda tanilishni ta&#39;minlaydi. Sinfdosh 3 dan 3 ni topsa — siluyetlar muvaffaqiyatli.</p><h3 id="_2-topshiriq-photoshop-sozlamalari-oson" tabindex="-1">2-topshiriq. Photoshop sozlamalari (oson) <a class="header-anchor" href="#_2-topshiriq-photoshop-sozlamalari-oson" aria-label="Permalink to &quot;2-topshiriq. Photoshop sozlamalari (oson)&quot;">​</a></h3><p>32×32 px piksel-art hujjatini tayyorlang: shaffof fon, 1 px grid, Pencil 1 px, Nearest Neighbor interpolyatsiya.</p><p><strong>Yechim:</strong> File → New (32×32, Transparent) → Preferences → Guides, Grid &amp; Slices (Gridline Every 1 px, Subdivisions 1) → View → Show → Grid → Pencil Tool (Shift + B), Size 1 px → Preferences → General → Image Interpolation: Nearest Neighbor. Tekshirish: 1 px chizilganda chetlari xira emas, to&#39;liq kvadrat.</p><h3 id="_3-topshiriq-qahramon-spraytini-5-qatlamda-chizish-o-rta" tabindex="-1">3-topshiriq. Qahramon spraytini 5 qatlamda chizish (o&#39;rta) <a class="header-anchor" href="#_3-topshiriq-qahramon-spraytini-5-qatlamda-chizish-o-rta" aria-label="Permalink to &quot;3-topshiriq. Qahramon spraytini 5 qatlamda chizish (o&#39;rta)&quot;">​</a></h3><p>1-topshiriqdagi siluyetlardan birini tanlab, 10-dars palitrasidan 5–6 rang bilan to&#39;liq spraytga aylantiring: flat, soya, yorug&#39;lik (yuqori chapdan), kontur. Qatlamlarni nomlang.</p><p><strong>Yechim:</strong></p><ol><li><code>01_siluyet</code> ustida <code>02_flat</code>: teri, kiyim, soch, aksessuar — har biri bitta rang (Pencil, Paint Bucket Anti-alias o&#39;chiq).</li><li><code>03_soya</code> (Clipping Mask): pastki o&#39;ng tomonlarga hue shifting soyalar.</li><li><code>04_yoruglik</code>: yuqori chap qirralarga 1 px yorug&#39;lik.</li><li><code>05_kontur</code>: 1 px kontur, doubles va orphan piksellar tozalanadi.</li><li><code>01_siluyet</code> yashiriladi. Kulrang testda qahramon fondan ajraladi; Export As → PNG <code>sprayt_qahramon_idle_32.png</code>.</li></ol><h3 id="_4-topshiriq-obyektlar-to-plami-va-idle-animatsiya-qiyin" tabindex="-1">4-topshiriq. Obyektlar to&#39;plami va idle animatsiya (qiyin) <a class="header-anchor" href="#_4-topshiriq-obyektlar-to-plami-va-idle-animatsiya-qiyin" aria-label="Permalink to &quot;4-topshiriq. Obyektlar to&#39;plami va idle animatsiya (qiyin)&quot;">​</a></h3><p>16×16 px da 3 ta obyekt (tanga, jon zelyesi, kalit) chizing va qahramoningiz uchun 2 kadrli idle animatsiyani Timeline&#39;da yarating. Natijani GIF ko&#39;rinishida saqlang.</p><p><strong>Yechim:</strong></p><ul><li>Obyektlar: bir xil kontur rangi va yorug&#39;lik yo&#39;nalishi, rang kodlash (oltin, qizil, kumush/oltin).</li><li>Idle: guruh nusxasi, tana va bosh 1 px pastga, Timeline → Create Frame Animation, 2 kadr × 0.5 s, Forever.</li><li>File → Export → Save for Web (Legacy) → GIF, Transparency ✓, Image Size 800% (Nearest Neighbor) → <code>qahramon_idle.gif</code>. Tekshirish: qahramon «nafas olayotgandek» yumshoq tebranadi, oyoqlar sakramaydi.</li></ul><hr>',15))]),i("div",q,[i("h2",c,[t(r,{name:"file-text"}),a[9]||(a[9]=s(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=o("<ol><li>Retro o&#39;yin uchun qahramon spraytining odatiy o&#39;lchami qancha? <ul><li><em>Javob:</em> 32×32 piksel (mayda obyektlar 16×16).</li></ul></li><li>Nima uchun avval siluyet chiziladi? <ul><li><em>Javob:</em> Qahramon shakli rangsiz ham tanilishini tekshirish uchun.</li></ul></li><li>Piksel-artda nega Brush emas, Pencil Tool ishlatiladi? <ul><li><em>Javob:</em> Pencil qattiq chetli piksel qo&#39;yadi; Brush chetlarni yumshatib xira piksellar hosil qiladi.</li></ul></li><li>Spraytni kattalashtirganda qaysi interpolyatsiya tanlanadi? <ul><li><em>Javob:</em> Nearest Neighbor — piksellar keskin saqlanadi.</li></ul></li><li>Barcha spraytlarda yorug&#39;lik manbai qayerda bo&#39;lishi kerak? <ul><li><em>Javob:</em> Bir xil joyda, odatda yuqori chapda.</li></ul></li></ol><hr>",2))]),i("div",b,[i("h2",v,[t(r,{name:"file-text"}),a[12]||(a[12]=s(" Keng tarqalgan xatolar va ularning oldini olish ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#keng-tarqalgan-xatolar-va-ularning-oldini-olish","aria-label":'Permalink to "<Icon name="file-text" /> Keng tarqalgan xatolar va ularning oldini olish"'},"​",-1))]),a[14]||(a[14]=o("<ul><li><strong>Brush Tool bilan chizish:</strong> xira chetlar — Pencil va Anti-alias o&#39;chiq ishlating.</li><li><strong>Bicubic bilan kattalashtirish:</strong> sprayt loyqa bo&#39;ladi — Nearest Neighbor.</li><li><strong>Juda ko&#39;p rang va gradient:</strong> 32 px da shovqin — 4–6 rang yetarli.</li><li><strong>Har xil yorug&#39;lik yo&#39;nalishi:</strong> bir spraytda chapdan, boshqasida o&#39;ngdan — sahna «buziladi».</li><li><strong>Masshtab buzilishi:</strong> tanga qahramondan katta — barcha spraytlarni yonma-yon tekshiring.</li><li><strong>Oq fonda saqlash:</strong> Transparent hujjat va PNG/GIF Transparency ni tekshiring.</li></ul>",1))])])}const j=n(d,[["render",f]]);export{N as __pageData,j as default};
